package com.collegeerp.erp.email.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
@Component public class TemplateDataCipher{private final SecretKey key;private final SecureRandom random=new SecureRandom();public TemplateDataCipher(@Value("${app.jwt.secret}")String secret){try{key=new SecretKeySpec(MessageDigest.getInstance("SHA-256").digest(secret.getBytes(StandardCharsets.UTF_8)),"AES");}catch(Exception e){throw new IllegalStateException(e);}}public String encrypt(String plain){try{byte[]iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));byte[]encrypted=c.doFinal(plain.getBytes(StandardCharsets.UTF_8)),combined=new byte[iv.length+encrypted.length];System.arraycopy(iv,0,combined,0,iv.length);System.arraycopy(encrypted,0,combined,iv.length,encrypted.length);return Base64.getEncoder().encodeToString(combined);}catch(Exception e){throw new IllegalStateException("Could not protect email template data",e);}}public String decrypt(String value){try{byte[]combined=Base64.getDecoder().decode(value),iv=Arrays.copyOfRange(combined,0,12),encrypted=Arrays.copyOfRange(combined,12,combined.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,iv));return new String(c.doFinal(encrypted),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Could not read protected email template data",e);}}}
